-- Generated by apply_drivetime.R (from drivetime.R).
-- "Max drive time without leaving the district": the OSRM graph is clipped to the
-- district polygon, so this measures internal road connectivity, not absolute distance.
-- max_drive_min is NULL where no sampled pair is road-connected (islands, severed halves);
-- max_drive_min_ferry covers those cases but is OSRM's synthetic ferry duration.
UPDATE puzzles p SET census = census || jsonb_build_object(
  'max_drive_min', n.max_drive_min,
  'max_drive_from', jsonb_build_array(n.from_lon, n.from_lat),
  'max_drive_to', jsonb_build_array(n.to_lon, n.to_lat),
  'max_drive_min_ferry', n.max_drive_min_ferry,
  'max_drive_ferry_from', jsonb_build_array(n.ferry_from_lon, n.ferry_from_lat),
  'max_drive_ferry_to', jsonb_build_array(n.ferry_to_lon, n.ferry_to_lat),
  'max_drive_connected', n.connected,
  'max_drive_component', n.component,
  'max_drive_points', n.points,
  'max_drive_route_mi', n.max_route_mi,
  'max_drive_route', n.max_route_poly,
  'span_drive_min', n.span_drive_min,
  'span_mi', n.span_mi,
  'span_route_mi', n.span_route_mi,
  'span_from', jsonb_build_array(n.span_from_lon, n.span_from_lat),
  'span_to', jsonb_build_array(n.span_to_lon, n.span_to_lat),
  'span_route', n.span_route_poly)
